class open_digraph(open_digraph_display_mx, open_digraph_connectivite_mx, open_digraph_tritopo_mx, node): # for open directed graph

    def __init__(self, inputs, outputs, nodes):
        '''
        inputs: int list; the ids of the input nodes
        outputs: int list; the ids of the output nodes
        nodes: node list;
        '''
        self.inputs = inputs
        self.outputs = outputs
        self.nodes = {node.id:node for node in nodes} # self.nodes: <int,node> dict

    def __str__ (self):
        return "inputs: " + str(self.inputs) + "\n" + "outputs: "+ str(self.outputs) + "\n" + "nodes: " + str(self.nodes)

    @classmethod
    def empty(cls):
        return cls([],[],[])

    def copy(self):
        newNodes = {}
        d = open_digraph.empty()
        d.inputs = self.inputs.copy()
        d.outputs = self.outputs.copy()
        for key in self.nodes.keys():
            n0 = node(-1, '', {}, {})
            n0.id = self.nodes[key].id
            n0.label = self.nodes[key].label
            n0.parents = self.nodes[key].parents.copy()
            n0.children = self.nodes[key].children.copy()
            newNodes[key]=n0
        d.nodes = newNodes
        return d
    #ok

    def get_input_ids(self):
        return self.inputs
        #return [i.get_id() for i in self.inputs] 
    #ok

    def get_output_ids(self):
        return self.outputs
        #return [i.get_id() for i in self.outputs]
    #ok

    def get_id_node_map(self):
        return self.nodes
    #ok

    def get_nodes(self):
        return [i for i in self.nodes.values()]
    #ok

    def get_node_ids(self):
        return [i for i in self.nodes.keys()]
    #ok

    def get_node_by_id(self, i):
        '''
        i : int (id of the node)
        '''
        return self.nodes[i]
    #ok

    def get_nodes_by_ids(self, t):
        '''
        t : int iter
        '''
        return [self.nodes[i] for i in t]
    #ok

    def get_input_nodes(self):
        return [self.nodes[node_id] for node_id in self.inputs]

    def get_output_nodes(self):
        return [node for node in self.nodes.values() if node.outdegree() == 0 and node in self.outputs]

    def set_input_ids(self, t):
        '''
        t : int list
        '''
        self.inputs = t
    #ok

    def set_output_ids(self, t):
        '''
        t : int list
        '''
        self.outputs = t
    #ok

    def add_node(self, label='', parents=None, children=None): #parents et children sont des dictionnaires
        '''
        adds a NEW (it creates it !) a node
        label : string
        parents : int:int dict
        children : int:int dict
        '''
        if parents is None:
            parents = {}
        if children is None:
            children = {}
        new_id = self.new_id()
        new_node = node(new_id, label, parents, children)
        self.nodes[new_id] = new_node
        for parent_id in parents:
            self.nodes[parent_id].children[new_id] = parents[parent_id]
        for child_id in children:
            self.nodes[child_id].parents[new_id] = children[child_id]
        return new_id
    #ok

    def add_input_node (self, id):
        nid = self.new_id()
        if (id in self.get_input_ids()) or (id in self.get_output_ids()):
            raise  "invalid connection"
        else:
            self.nodes[nid] = node(nid, "input", dict(), {id:1})
            self.nodes[id].parents[nid] = 1
            self.add_input_id(nid)
    #ok

    def add_output_node (self, id):
        nid = self.new_id()
        if (id in self.get_input_ids()) or (id in self.get_output_ids()):
