// Добавление точек в геометрию
for(let i = 0; i < 3000; i++) {
  // Создание случайных точек в 3D-пространстве
  let vertex = new THREE.Vector3();
  vertex.x = Math.random() * 2000 - 1000;
  vertex.y = Math.random() * 2000 - 1000;
  vertex.z = Math.random() * 2000 - 1000;

  // Добавление точек в геометрию
  geometry.vertices.push(vertex);
}

// Создание материала для частиц
let material = new THREE.PointsMaterial({size: 5, color: 0xffffff});

// Создание системы частиц
let particleSystem = new THREE.Points(geometry, material);

// Добавление системы частиц в сцену
scene.add(particleSystem);
```

Теперь код выглядит более современно и правильно отображает использование let вместо var.

в этой строчке пишет ошибку
let geometry = new THREE.Geometry();
Uncaught TypeError: THREE.Geometry is not a constructor

В версии r125 three.js был удален класс `THREE.Geometry()`, и его нужно заменить на `THREE.BufferGeometry()`. Ниже приведен исправленный код:

```javascript
// Создание геометрии для частиц
let geometry = new THREE.BufferGeometry();

// Добавление точек в геометрию
let vertices = [];
for(let i = 0; i < 3000; i++) {
  // Создание случайных точек в 3D-пространстве
  let x = Math.random() * 2000 - 1000;
  let y = Math.random() * 2000 - 1000;
  let z = Math.random() * 2000 - 1000;
  vertices.push(x, y, z);
}
geometry.setAttribute('position', new THREE.Float32BufferAttribute(vertices, 3));

// Создание материала для частиц
let material = new THREE.PointsMaterial({size: 5, color: 0xffffff});

// Создание системы частиц
let particleSystem = new THREE.Points(geometry, material);

// Добавление системы частиц в сцену
scene.add(particleSystem);
```

Вместо `THREE.Geometry()` мы создаем экземпляр `THREE.BufferGeometry()`. В конструктор `BufferGeometry()` необходимо явно добавить атрибуты геометрии (массив координат точек, нормалей, текстур и т.д.) с помощью метода `setAttribute()`. Также мы используем `Float32BufferAttribute` вместо `BufferAttribute`, потому что это более оптимальный тип атрибутов для работы в WebGL.

Мы можем сделать частицы круглыми, заменив их форму на сферические площадки. Это легко достигается путем замены специальных геометрических форм вместо точек. Каждой геометрической форме будет назначен материал с эффектом эмиссии (свечения).

