首先需要安装grpc-web：

```bash
npm install grpc-web
```

接下来，需要创建一个gRPC服务端和一个gRPC客户端。以下是一个简单的例子：

定义.proto文件：

```protobuf
syntax = "proto3";

package hello;

service HelloService {
    rpc SayHello(HelloRequest) returns (HelloResponse) {}
}

message HelloRequest {
    string name = 1;
}

message HelloResponse {
    string message = 1;
}
```

生成.proto文件代码：

```bash
protoc --proto_path=src/ --js_out=import_style=commonjs,binary:src/ --grpc-web_out=import_style=typescript,mode=grpcwebtext:src/ hello.proto
```

在服务端实现HelloService：

```javascript
const grpc = require('grpc');
const protoLoader = require('@grpc/proto-loader');

const packageDefinition = protoLoader.loadSync('src/hello.proto');
const helloPackage = grpc.loadPackageDefinition(packageDefinition).hello;

function sayHello(call, callback) {
  const name = call.request.name;
  callback(null, { message: `Hello, ${name}!`});
}

const server = new grpc.Server();
server.addService(helloPackage.HelloService.service, {
  sayHello
});

server.bind(`0.0.0.0:${port}`, grpc.ServerCredentials.createInsecure());
server.start();
```

在客户端调用：

```javascript
import * as grpcWeb from 'grpc-web';
import { HelloServiceClient } from './proto/hello_pb_service';
import { HelloRequest, HelloResponse } from './proto/hello_pb';

const client = new HelloServiceClient('http://localhost:8080');

const request = new HelloRequest();
request.setName('World');

client.sayHello(request, {}, (err: grpcWeb.Error, response: HelloResponse) => {
  if (err) {
    console.log(`Error: ${err.message}`);
    return;
  }
  console.log(`Response: ${response.getMessage()}`);
});
