let player1Card = "";
let player2Card = "";
let player1Hand = [];
let player2Hand = [];

// Shuffle the deck of cards
function shuffle(deck) {
  for (let i = deck.length - 1; i > 0; i--) {
    let j = Math.floor(Math.random() * (i + 1));
    [deck[i], deck[j]] = [deck[j], deck[i]];
  }
  return deck;
}

// Deal the cards to the players
function dealCards(deck) {
  for (let i = 0; i < 2; i++) {
    player1Hand.push(deck.pop());
    player2Hand.push(deck.pop());
  }
}

// Play the game
function playGame() {
  // Initialise the game
  let deck = shuffle(cards);
  dealCards(deck);

  // Play the game until there is a winner
  while (!winner) {
    // Show the current player and turn
    console.log(`Turn ${currentTurn}: ${currentPlayer}'s turn`);

    // Show the player's current hand
    console.log(`Your current hand is: ${currentPlayer === player1 ? player1Hand : player2Hand}`);

    // Get the player's selected card
    let selectedCard = parseInt(prompt("Select a card to play:"));

    // Get the opponent's card
    let opponentCard = currentPlayer === player1 ? player2Hand[0] : player1Hand[0];

    // Compare the cards
    let playerCard = currentPlayer === player1 ? player1Hand[selectedCard] : player2Hand[selectedCard];
    if (playerCard.strength > opponentCard.strength) {
      console.log(`${currentPlayer} wins!`);
      winner = currentPlayer;
    } else if (playerCard.strength < opponentCard.strength) {
      console.log(`${currentPlayer === player1 ? player2 : player1} wins!`);
      winner = currentPlayer === player1 ? player2 : player1;
    } else {
      console.log("It's a tie! Keep playing.");
    }

    // Discard the played card
    currentPlayer === player1 ? (player1Hand[selectedCard] = null) : (player2Hand[selectedCard] = null);
    currentPlayer = currentPlayer === player1 ? player2 : player1;

    // Increase the turn count
    currentTurn++;
  }

  // Show the winner
  console.log(`Congratulations ${winner}! You have won the game!`);
}

// Start the game
playGame();
