public abstract class PaymentHandler
{
    protected PaymentHandler successor;

    public void SetSuccessor(PaymentHandler successor)
    {
        this.successor = successor;
    }

    public abstract bool ProcessPayment(decimal amount);
}

public class PayPalHandler : PaymentHandler
{
    private const decimal MAX_AMOUNT = 1000m;

    public override bool ProcessPayment(decimal amount)
    {
        if (amount <= MAX_AMOUNT)
        {
            Console.WriteLine("PayPal processed the payment of {0:c}", amount);
            return true;
        }
        else if (successor != null)
        {
            return successor.ProcessPayment(amount);
        }
        else
        {
            Console.WriteLine("Payment cannot be processed");
            return false;
        }
    }
}

public class CreditCardHandler : PaymentHandler
{
    private const decimal MAX_AMOUNT = 5000m;

    public override bool ProcessPayment(decimal amount)
    {
        if (amount <= MAX_AMOUNT)
        {
            Console.WriteLine("Credit card processed the payment of {0:c}", amount);
            return true;
        }
        else if (successor != null) 
        {
            return successor.ProcessPayment(amount);
        }
        else
        {
            Console.WriteLine("Payment cannot be processed");
            return false;
        }
    }
}

public class BankTransferHandler : PaymentHandler
{
    private const decimal MAX_AMOUNT = 10000m;

    public override bool ProcessPayment(decimal amount)
    {
        if (amount <= MAX_AMOUNT)
        {
            Console.WriteLine("Bank transfer processed the payment of {0:c}", amount);
            return true;
        }
        else if (successor != null)
        {
            return successor.ProcessPayment(amount);
        }
        else
        {
            Console.WriteLine("Payment cannot be processed");
            return false;
        }
    }
}

// Пример использования:
static void Main(string[] args)
{
    PaymentHandler processor = new PayPalHandler();
    processor.SetSuccessor(new CreditCardHandler());
    processor.SetSuccessor(new BankTransferHandler());

    bool success = processor.ProcessPayment(2500m);
    Console.WriteLine("Payment processed: " + success);
}
```

В этом примере класс PaymentHandler определяет общий интерфейс и свойство-указатель на следующий обработчик в цепочке. Классы PayPalHandler, CreditCardHandler и BankTransferHandler представляют конкретные обработчики платежей, которые могут обработать платеж или передать его следующему обработчику, если они не могут обработать платеж самостоятельно.

В классе клиента (Main) создается цепочка обработчиков и передается платеж для обработки. Обработчики пропускают платеж через цепочку, пока один из них не может обработать платеж или цепочка не закончилась. Клиент получает результат обработки платежа и принимает решение о продолжении выполнения операции в зависимости от успешности обработки.

В данном примере используются три различных обработчика платежей для обработки платежей соответствующей суммы: PayPalHandler для платежей до 1000 долларов, CreditCardHandler для платежей до 5000 долларов и BankTransferHandler для платежей до 10000 долларов. Если платеж не может быть обработан ни одним из обработчиков, то клиент получает сообщение "Payment cannot be processed".

Вот пример реализации паттерна наблюдатель на C#:

```
// Интерфейс для наблюдателя
public interface IObserver
{
    void Update(string message);
}

// Интерфейс для объекта, за которым наблюдают
public interface ISubject
{
    void RegisterObserver(IObserver observer);
    void RemoveObserver(IObserver observer);
    void NotifyObservers(string message);
}

// Реализация наблюдаемого объекта
public class WeatherStation : ISubject
{
    private List<IObserver> observers = new List<IObserver>();
    private string weatherData;

    public void RegisterObserver(IObserver observer)
    {
        observers.Add(observer);
    }

    public void RemoveObserver(IObserver observer)
    {
        observers.Remove(observer);
    }

    public void NotifyObservers(string message)
    {
        foreach (IObserver observer in observers)
        {
            observer.Update(message);
        }
    }

    // Данные о погоде указываются наблюдаемым объектом 
    // и отправляются всем наблюдателям в виде уведомления
    public void SetWeatherData(string data)
    {
        weatherData = data;
        NotifyObservers(weatherData);
    }
}

// Реализация наблюдателя
public class WeatherDisplay : IObserver
{
    public void Update(string message)
    {
        Console.WriteLine("Weather updated: " + message);
    }
}

// Пример использования
static void Main(string[] args)
{
    WeatherStation station = new WeatherStation();
    WeatherDisplay display1 = new WeatherDisplay();
    WeatherDisplay display2 = new WeatherDisplay();

    // Заводим два наблюдателя
    station.RegisterObserver(display1);
    station.RegisterObserver(display2);

    // Устанавливаем данные о погоде, которые должны быть отправлены наблюдателям
    station.SetWeatherData("sunny");

    // Отписываем первый дисплей от уведомлений
    station.RemoveObserver(display1);

    // Устанавливаем новые данные
    station.SetWeatherData("rainy");
}
```

Эта реализация паттерна наблюдатель состоит из трех основных компонентов: наблюдаемого объекта (WeatherStation), интерфейса для объекта (ISubject), за которым наблюдают, интерфейса для наблюдателя (IObserver) и класса для наблюдателя (WeatherDisplay).

