Here's an example of creating a mouse-controlled sphere in p5.js.

```javascript
let spherePos; // stores the position of the sphere

function setup() {
  createCanvas(400, 400, WEBGL);
  spherePos = createVector(0, 0, 0); // initialize the sphere position at the center of the canvas
}

function draw() {
  background(220);

  // move the sphere towards the mouse position
  let mousePos = createVector(mouseX - width/2, mouseY - height/2, 0); // get the mouse position relative to the canvas center
  let direction = createVector(mousePos.x, mousePos.y, spherePos.z).normalize(); // get a normalized direction vector towards the mouse
  let speed = 5; // set the movement speed
  spherePos.add(direction.mult(speed)); // move the sphere

  // draw the sphere
  push();
  translate(spherePos.x, spherePos.y, spherePos.z); // move to the sphere position
  sphere(50); // draw a sphere with a radius of 50
  pop();
}
```

This code creates a 3D canvas using WEBGL and initializes the sphere position at the center of the canvas. In the `draw` function, it calculates the normalized direction vector towards the mouse and adds it to the sphere's position with a speed of 5. Finally, it draws a sphere with a radius of 50 at the updated sphere position using the `sphere` function.

When you run this code, you should see a sphere following your mouse movement.

Here's an example of adding 5 randomly positioned buttons on the sphere in p5.js:

```javascript
let spherePos; // stores the position of the sphere
let buttons = []; // an array to store the button positions

function setup() {
  createCanvas(400, 400, WEBGL);
  spherePos = createVector(0, 0, 0); // initialize the sphere position at the center of the canvas

  // create 5 buttons at random positions on the sphere
  for (let i = 0; i < 5; i++) {
    let x = random(-1, 1);
    let y = random(-1, 1);
    let z = random(-1, 1);
    buttons.push(createVector(x, y, z).normalize().mult(50)); // normalize the position vector and scale it by the radius of the sphere
  }
}

function draw() {
  background(220);

  // move the sphere towards the mouse position
  let mousePos = createVector(mouseX - width/2, mouseY - height/2, 0); // get the mouse position relative to the canvas center
  let direction = createVector(mousePos.x, mousePos.y, spherePos.z).normalize(); // get a normalized direction vector towards the mouse
  let speed = 5; // set the movement speed
  spherePos.add(direction.mult(speed)); // move the sphere

  // draw the sphere and the buttons
  push();
  translate(spherePos.x, spherePos.y, spherePos.z); // move to the sphere position
  sphere(50); // draw a sphere with a radius of 50
  for (let button of buttons) {
    push();
    translate(button.x, button.y, button.z); // move to the button position
    fill(255, 0, 0);
    sphere(5); // draw a small red sphere as the button
    pop();
  }
  pop();
}
```

This code initializes an empty array `buttons` to store the button positions. In the `setup` function, it creates 5 random positions on the sphere and adds them to the `buttons` array by normalizing the position vector and scaling it by the radius of the sphere.

In the `draw` function, it moves the sphere towards the mouse position as in the previous example, and then draws the sphere and the buttons. For each button position in the `buttons` array, it moves to the button position, fills a red color, and draws a small sphere with a radius of 5.

When you run this code, you should see a sphere with 5 red buttons at random positions following your mouse movement.

