```html
<!DOCTYPE html>
<html>
<head>
  <meta charset="UTF-8">
  <title>Sphere with 5 buttons</title>
  <!-- Include p5.js library -->
  <script src="https://cdnjs.cloudflare.com/ajax/libs/p5.js/1.4.0/p5.min.js"></script>
